head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDFIL45501";
scwin.row1 = 1;
scwin.row2 = 1;
scwin.row3 = 1;
scwin.row4 = 1;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
        scwin.init_gridRows();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil45501.onpageload' });
    }
};

/**
 * @method
 * @name init_gridRows
 * @description 초기 빈 입력행 — as-is 가 정적으로 그려 두던 빈 행을 그리드에서 다시 세운다(명부 initial_rows).
 * @returns {void}
 * @hidden N
 */
scwin.init_gridRows = function () {
    {
        const d = $c.util.getComponent("dlt_capChg1");
        if (!d || typeof d.insertRow !== "function") { /* TODO Stage2: [sdd] 초기 빈 행 대상 부재:  "dlt_capChg1 */ }
        else { for (let i = 0; i < 1; i++) { d.insertRow(); } }
    }
    {
        const d = $c.util.getComponent("dlt_capChg2");
        if (!d || typeof d.insertRow !== "function") { /* TODO Stage2: [sdd] 초기 빈 행 대상 부재:  "dlt_capChg2 */ }
        else { for (let i = 0; i < 1; i++) { d.insertRow(); } }
    }
    {
        const d = $c.util.getComponent("dlt_capChg3");
        if (!d || typeof d.insertRow !== "function") { /* TODO Stage2: [sdd] 초기 빈 행 대상 부재:  "dlt_capChg3 */ }
        else { for (let i = 0; i < 1; i++) { d.insertRow(); } }
    }
    {
        const d = $c.util.getComponent("dlt_capChg4");
        if (!d || typeof d.insertRow !== "function") { /* TODO Stage2: [sdd] 초기 빈 행 대상 부재:  "dlt_capChg4 */ }
        else { for (let i = 0; i < 1; i++) { d.insertRow(); } }
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name ipt_capitalstock_onfocus
 * @description ipt_capitalstock 포커스 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_capitalstock_onfocus = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        scwin.unformat(selfVar); selfVar.select();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil45501.ipt_capitalstock_onfocus' }); }
};

/**
 * @method
 * @name ipt_capitalstock_onblur
 * @description ipt_capitalstock 포커스 이탈 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ipt_capitalstock_onblur = async function(e){
    try {
        await scwin.numFormat($c.util.getComponent("ipt_capitalstock"));

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil45501.ipt_capitalstock_onblur' }); }
};

